SELECT *
FROM plt_collection_result_consumption
WHERE tenant_id = #{query.tenantId}
  AND platform_task_id = #{query.platformTaskId}
  AND consumer_context = #{query.consumerContext}
  AND consumer_object_type = #{query.consumerObjectType}
  AND consumer_object_id = #{query.consumerObjectId}
  AND result_version = #{query.resultVersion}
  AND deleted = b'0'
